フーリエ変換を $\tilde f(k)=\displaystyle\int_{-\infty}^{\infty}f(x)e^{-ikx}dx$ と定める．
\begin{enumerate}
\item $f(x)=e^{-x^2/(2\sigma^2)}$ のフーリエ変換 $\tilde f(k)$ を求めよ．
\item 波動関数 $\psi(x)\propto e^{-x^2/(4\sigma^2)}$ では位置の標準偏差が $\sigma$ である．運動量の標準偏差 $\sigma_p$ を求めよ．
\item デルタ関数の公式 $\delta(g(x))=\sum_i\dfrac{\delta(x-x_i)}{|g'(x_i)|}$（$x_i$ は $g$ の零点）を用いて $\displaystyle\int_{-\infty}^{\infty}\delta(x^2-a^2)\,e^{-x}dx$（$a>0$）を求めよ．
\end{enumerate}

フーリエ変換は $\hat f(k)=\dfrac{1}{\sqrt{2\pi}}\displaystyle\int_{-\infty}^{\infty}f(x)e^{-ikx}dx$，逆変換は $f(x)=\dfrac{1}{\sqrt{2\pi}}\displaystyle\int_{-\infty}^{\infty}\hat f(k)e^{ikx}dk$ で定義する．
\begin{enumerate}
\item 次の性質を定義から示せ：(a) $\mathcal F[f(x-c)]=e^{-ikc}\hat f(k)$，(b) $\mathcal F[e^{ik_0x}f(x)]=\hat f(k-k_0)$，(c) $f$ が実関数 $\iff$ $\overline{\hat f(k)}=\hat f(-k)$．
\item 実関数 $f$ のフーリエ変換が，ある実定数 $c$ と実数値関数 $R(k)$ を用いて $\hat f(k)=e^{-ikc}R(k)$ と書けたとする．このとき $f$ は直線 $x=c$ に関して対称，すなわち $f(c+x)=f(c-x)$ であることを示せ．
\item 位置 $c$ を中心とし，搬送波数 $k_0$ をもつ波束 $f(x)=e^{-a(x-c)^2}\cos k_0x$（$a>0$）のフーリエ変換を，積分を新たに計算せず（1）の性質と $\mathcal F[e^{-ax^2}]=\frac{1}{\sqrt{2a}}e^{-k^2/4a}$ だけから求めよ．また，この $f$ は一般に $x=c$ に関して対称ではない．（2）の主張と矛盾しないことを $\hat f$ の形から説明せよ．
\end{enumerate}

抵抗 $R$ とコンデンサー $C$ の直列回路に電圧 $V(t)$ を加える．電荷 $q$ は $R\dot q+q/C=V(t)$，$q(0)=0$ に従う．$\tau_0=RC$ とする．
\begin{enumerate}
\item $V(t)=V_0$（$0<t<T$），$V(t)=0$（$t>T$）の矩形パルスのとき，ラプラス変換の推移則 $\mathcal L[f(t-T)\theta(t-T)]=e^{-sT}\tilde f(s)$ を用いて $q(t)$ を求め，$t>T$ での形を簡潔に書け．
\item $V(t)=V_0e^{-t/\tau_0}$（回路の時定数と同じ速さで減衰する電圧）のとき，$\mathcal L[e^{\alpha t}f(t)]=\tilde f(s-\alpha)$ を用いて $q(t)$ を求めよ．
\item (2) で電荷が最大となる時刻と最大値を求めよ．
\end{enumerate}

周期 $T$ の電圧 $V(t)$ が，$-T/2<t<0$ で $0$，$0<t<T/2$ で $V_0$ をとる方形波である（$\omega_0=2\pi/T$）．
\begin{enumerate}
\item $V(t)$ のフーリエ級数を求めよ．
\item この電圧を抵抗 $R$ に加えたときの平均電力のうち，直流成分による分と基本波（角周波数 $\omega_0$）成分による分をそれぞれ求めよ．交流成分の電力のうち基本波が占める割合を有効数字 3 桁で答えよ．
\item パーセバルの等式から $\displaystyle\sum_{k=1}^\infty\frac{1}{(2k-1)^2}$ を求めよ．
\end{enumerate}

$a>0$ とし，$h(x)=1\ (|x|<a/2)$，$h(x)=0\ (|x|>a/2)$ とする．フーリエ変換を $H(k)=\displaystyle\int_{-\infty}^{\infty}h(x)e^{-ikx}dx$，畳み込みを $(f*g)(x)=\displaystyle\int_{-\infty}^{\infty}f(x')g(x-x')\,dx'$ と定める．
\begin{enumerate}
\item $H(k)$ を求めよ．
\item $|x|<a$ で $(h*h)(x)$ を求めよ．（畳み込み定理より，そのフーリエ変換は $H(k)^2$ になる．）
\item プランシュレルの定理 $\displaystyle\int|h|^2dx=\frac{1}{2\pi}\int|H|^2dk$ を用いて $\displaystyle\int_{-\infty}^{\infty}\frac{\sin^2u}{u^2}\,du$ を求めよ．
\end{enumerate}

$-\pi<x<\pi$ で $f(x)=|x|$ とし，周期 $2\pi$ で拡張する．$f(x)=\dfrac{a_0}{2}+\displaystyle\sum_{n\ge1}a_n\cos nx$ と展開する．
\begin{enumerate}
\item $n$ が奇数のときの $a_n$ を求めよ（$a_0=\pi$，偶数の $n\ge2$ では $a_n=0$）．
\item $x=0$ を代入して $\displaystyle\sum_{n=1}^{\infty}\frac{1}{(2n-1)^2}$ を求めよ．
\item パーセバルの等式 $\dfrac{1}{\pi}\displaystyle\int_{-\pi}^{\pi}f^2dx=\frac{a_0^2}{2}+\sum a_n^2$ から $\displaystyle\sum_{n=1}^{\infty}\frac{1}{(2n-1)^4}$ を求めよ．
\end{enumerate}

デルタ関数とグリーン関数について答えよ．
\begin{enumerate}
\item 任意の滑らかな試験関数で積分することにより，$x\,\delta'(x)=c\,\delta(x)$ となる定数 $c$ を求めよ．
\item $\kappa>0$ とする．$\left(\dfrac{d^2}{dx^2}-\kappa^2\right)G(x)=\delta(x)$ を満たし，$|x|\to\infty$ で $0$ になる $G(x)$ を求め，$x>0$ での式を答えよ．
\item 3次元で $\nabla^2\dfrac1r=c'\,\delta^3(\boldsymbol{r})$ となる定数 $c'$ を求めよ．
\end{enumerate}

$a>0$ とする．
\begin{enumerate}
\item 部分積分を2回用いて $\displaystyle\int_0^\infty e^{-at}\cos bt\,dt=\frac{a}{a^2+b^2}$，$\displaystyle\int_0^\infty e^{-at}\sin bt\,dt=\frac{b}{a^2+b^2}$ を示せ．
\item $\displaystyle\int_0^\infty te^{-at}\cos bt\,dt$ を，$a$ についての微分で求めよ．
\item $t\geqq0$ で $f(t)=e^{-\gamma t}e^{i\omega_0t}$ の振動のパワースペクトル $|\tilde f(\omega)|^2=\left|\int_0^\infty f(t)e^{-i\omega t}dt\right|^2$ を求め，半値全幅を答えよ．
\end{enumerate}

周期 $2L$ の関数を $f(x)=\dfrac1{\sqrt{2L}}\sum_{n=-\infty}^{\infty}c_ne^{in\pi x/L}$，$c_n=\dfrac1{\sqrt{2L}}\int_{-L}^{L}f(x)e^{-in\pi x/L}dx$ と展開する．
\begin{enumerate}
\item 指数関数の直交性 $\int_{-L}^{L}e^{i(n-m)\pi x/L}dx=2L\delta_{nm}$ を用いて，$\displaystyle\int_{-L}^{L}|f(x)|^2dx=\sum_{n=-\infty}^{\infty}|c_n|^2$（パーセバルの等式）を示せ．この展開の規格化 $1/\sqrt{2L}$ が対称に選ばれていることの利点を述べよ．
\item $-L\le x<L$ で $f(x)=e^{ax}$（$a>0$）とし，周期 $2L$ で拡張した関数の $c_n$ を求めよ．
\item (1)(2) から，$\beta>0$ に対して $\displaystyle\sum_{n=-\infty}^{\infty}\frac1{n^2+\beta^2}$ を閉じた形で求めよ．さらに $\beta\to0$ の極限を考えて $\sum_{n=1}^\infty 1/n^2$ を求めよ．
\end{enumerate}

周期 $2L$ の関数 $f$ の三角関数表示 $f=A_0+\sum_{n\ge1}\left[A_n\cos\frac{n\pi x}{L}+B_n\sin\frac{n\pi x}{L}\right]$ と指数関数表示 $f=\frac{1}{\sqrt{2L}}\sum_{n\in\mathbb Z}c_ne^{in\pi x/L}$ を考える．
\begin{enumerate}
\item オイラーの関係式を用いて $c_n$（$n\ge1$），$c_{-n}$，$c_0$ を $A_n,B_n,A_0$ で表せ．$f$ が実数値であることは $c_n$ についてのどんな条件と同値か．
\item $f(x+L)=-f(x)$（半周期ずらすと符号反転）が成り立つことと，偶数番目の $c_n$ がすべて $0$ になることが同値であることを示せ．
\item $f(x)=\exp\left(\alpha\cos\frac{\pi x}{L}\right)$（$\alpha$ は実数）について，$c_n=\sqrt{2L}\,I_n(\alpha)$ と書けることを示せ．ここで $I_n(\alpha)=\frac1\pi\int_0^\pi e^{\alpha\cos\theta}\cos n\theta\,d\theta$（変形ベッセル関数）．さらに $\sum_{n\in\mathbb Z}I_n(\alpha)^2$ を $I_0$ を用いて表せ．
\end{enumerate}

交流電圧 $V_0\sin\omega t$ を全波整流した電圧 $V_{\rm in}(t)=V_0|\sin\omega t|$ を，抵抗 $R$ とコンデンサー $C$ の直列回路に加え，コンデンサーの両端電圧 $V_{\rm out}(t)$ を出力とする（RC ローパスフィルタ）．$V_{\rm out}$ は $RC\,\dot V_{\rm out}+V_{\rm out}=V_{\rm in}$ に従う．
\begin{enumerate}
\item $V_{\rm in}(t)$ の周期を答え，フーリエ級数に展開せよ．
\item 十分時間がたった後の定常状態での $V_{\rm out}(t)$ をフーリエ級数で表せ．
\item 出力の直流成分 $\bar V$ と，最も低い交流成分の振幅 $V_{\rm r}$ の比（リップル率）$V_{\rm r}/\bar V$ を求め，$\omega RC\gg1$ での近似式を示せ．
\end{enumerate}

フーリエ変換は $\hat f(k)=\dfrac{1}{\sqrt{2\pi}}\displaystyle\int_{-\infty}^{\infty}f(x)e^{-ikx}dx$，逆変換は $f(x)=\dfrac{1}{\sqrt{2\pi}}\displaystyle\int_{-\infty}^{\infty}\hat f(k)e^{ikx}dk$ で定義する．2 つの関数 $f,g$ に対するパーセバルの等式 $\displaystyle\int_{-\infty}^{\infty}\hat f(k)\overline{\hat g(k)}dk=\int_{-\infty}^{\infty}f(x)\overline{g(x)}dx$ を用いてよい．
\begin{enumerate}
\item $s_a(x)=\dfrac{\sin ax}{x}$（$a>0$）のフーリエ変換が $\hat s_a(k)=\sqrt{\dfrac{\pi}{2}}\,\chi_a(k)$（$\chi_a$ は $|k|<a$ で 1，$|k|>a$ で 0）となることを，$\chi_a$ の逆変換を計算することで示せ．
\item 遮断波数 $a,b$ の 2 つの理想ローパスフィルタのインパルス応答の重なり積分 $\displaystyle\int_{-\infty}^{\infty}\frac{\sin ax\,\sin bx}{x^2}dx$（$a,b>0$）を求めよ．
\item $\displaystyle I(a,c)=\int_{-\infty}^{\infty}\frac{\sin ax}{x(x^2+c^2)}dx$（$a,c>0$）を求めよ．さらに $a\to\infty$ と $c\to0$ の極限での振る舞いを，被積分関数から直接見積もった結果と比較せよ．
\end{enumerate}

$f(t)$ とその導関数のラプラス変換が存在するとき，$\mathcal L[f'](s)=s\tilde f(s)-f(0)$ が成り立つ．
\begin{enumerate}
\item この式から，（極限と積分の交換を認めて）初期値定理 $\displaystyle\lim_{s\to\infty}s\tilde f(s)=f(0)$ と，$f(\infty)=\lim_{t\to\infty}f(t)$ が存在するときの最終値定理 $\displaystyle\lim_{s\to+0}s\tilde f(s)=f(\infty)$ を導け．
\item 質量 $m$，抵抗係数 $\Gamma$，ばね定数 $K$ の振動子が静止状態（$x(0)=\dot x(0)=0$）から一定力 $F_0$ を受ける．$\tilde x(s)$ を求め，\textbf{逆変換せずに} $x(\infty)$，$\dot x(0)$，$\ddot x(0)$ を求めよ．
\item $\Gamma=0$ のとき $\lim_{s\to+0}s\tilde x(s)$ は有限値をもつが，$x(\infty)$ は存在しない．最終値定理が使える条件を $s\tilde x(s)$ の極の位置で述べよ．
\end{enumerate}

ばね・ダンパー系 $\ddot x+\gamma\dot x+kx=0$ が過減衰（$\gamma^2>4k$）であるとし，特性根を $-\lambda_1,-\lambda_2$（$0<\lambda_1<\lambda_2$，$\lambda_1+\lambda_2=\gamma$，$\lambda_1\lambda_2=k$）とする．初期条件は $x(0)=x_0>0$，$\dot x(0)=v_0$（原点に向けて押し出す場合 $v_0<0$）．
\begin{enumerate}
\item ラプラス変換により $x(t)$ を求めよ．
\item $t>0$ で $x$ が原点を通過する（オーバーシュートする）ための $v_0$ の条件と，そのときの通過時刻 $t^*$ を求めよ．通過は高々 1 回であることも示せ．
\item 臨界減衰 $\gamma^2=4k$ の場合の通過条件を求め，(2) の条件の極限と一致することを確かめよ．
\end{enumerate}

\begin{enumerate}
\item $\mathcal L[tf(t)]=-\dfrac{d\tilde f}{ds}$ を示し，$\mathcal L[t\sin at]$，$\mathcal L[t\cos at]$（$a>0$）を求めよ．
\item 減衰のない振動子 $\ddot x+\omega^2x=\dfrac{F_0}{m}\cos\omega t$ を $x(0)=\dot x(0)=0$ で解け（共鳴駆動）．
\item $f(t)/t$ のラプラス変換が存在するとき $\mathcal L\!\left[\dfrac{f(t)}{t}\right]=\displaystyle\int_s^\infty\tilde f(\sigma)d\sigma$ を示し，$\mathcal L\!\left[\dfrac{\sin t}{t}\right]$ を求めよ．さらに $s\to+0$ として $\displaystyle\int_0^\infty\frac{\sin t}{t}dt$ と，$\displaystyle\int_0^\infty\frac{e^{-t}\sin t}{t}dt$ の値を求めよ．
\end{enumerate}

固有角振動数 $b$ の減衰のない振動子が，静止状態（$x(0)=\dot x(0)=0$）から外力 $\dfrac{F_0}{m}\cos at$（$a>0$）で駆動される：$\ddot x+b^2x=\dfrac{F_0}{m}\cos at$．
\begin{enumerate}
\item 速度 $v=\dot x$ のラプラス変換 $\tilde v(s)$ を求め，$a\neq b$ のとき部分分数分解で $v(t)$ を求めよ．
\item $v(t)$ を $\cos$ 同士のたたみ込み積分の形に表し，$b=a$ の場合にたたみ込みを直接計算して $v(t)$ を求めよ．
\item (1) の結果で $b\to a$ の極限をとったものが (2) と一致することを確かめよ．また $b=a$ のとき $v(t)$ の振幅（包絡線）の増加率を求めよ．
\end{enumerate}

$g(x)$ の単純な零点を $x_i$ とすると $\delta(g(x))=\displaystyle\sum_i\frac{\delta(x-x_i)}{|g'(x_i)|}$ である．$a>0$ とする．
\begin{enumerate}
\item $\displaystyle\int_{-\infty}^{\infty}\delta(x^2-a^2)\,x^2\,dx$ を求めよ．
\item $\displaystyle\int_{1/2}^{\infty}\delta(\sin\pi x)\,e^{-x}\,dx$ を求めよ．
\item 相対論で $E=\sqrt{p^2+m^2}>0$ とする（$c=1$）．$\theta$ を階段関数として $\displaystyle\int_{-\infty}^{\infty}\delta(p_0^{\,2}-E^2)\,\theta(p_0)\,dp_0$ を求めよ．
\end{enumerate}

3次元フーリエ変換を $\tilde f(\boldsymbol{q})=\displaystyle\int f(r)\,e^{-i\boldsymbol{q}\cdot\boldsymbol{r}}d^3r$ と定め，$q=|\boldsymbol{q}|$，$\mu>0$ とする．
\begin{enumerate}
\item 球対称関数では $\tilde f=\dfrac{4\pi}{q}\displaystyle\int_0^\infty rf(r)\sin(qr)\,dr$ となる．$f=\dfrac{e^{-\mu r}}{r}$ のフーリエ変換を求めよ．
\item 質量 $m$ の粒子がポテンシャル $V(r)=V_0\dfrac{e^{-\mu r}}{r}$ で散乱される．第1ボルン近似の散乱振幅 $f=-\dfrac{m}{2\pi\hbar^2}\tilde V(\boldsymbol{q})$ を求めよ．
\item $f=e^{-\mu r}$ のフーリエ変換を求めよ．
\end{enumerate}

$0\le x\le L$ で定義された滑らかな関数 $f(x)$（$f(0)=f(L)=0$）の正弦級数 $f(x)=\sum_{n\ge1}b_n\sin\frac{n\pi x}{L}$ を考える．
\begin{enumerate}
\item $f(x)=x(L-x)$ の $b_n$ を求め，$b_n=O(n^{-3})$ であることを確かめよ．$x=L/2$ を代入して $\displaystyle\sum_{j=0}^\infty\frac{(-1)^j}{(2j+1)^3}$ の値を求めよ．
\item 部分積分を繰り返すことにより，$b_n$ の $1/n^3$ の項が $f''(0)$ と $f''(L)$ だけで決まることを示せ（$1/n^3$ の係数を具体的に書け）．これを $f$ を原点対称に拡張して得られる周期 $2L$ の関数 $\tilde f$ の滑らかさの言葉で解釈せよ．
\item $f(0)=f(L)=0$，$f''(0)=f''(L)=0$，$f'(0)=1$ を満たす最低次の多項式 $f$ を求め，その $b_n$ を計算せよ．さらにそれを用いて $\displaystyle\sum_{j=0}^\infty\frac{(-1)^j}{(2j+1)^5}$ の値を求めよ．
\end{enumerate}

\begin{enumerate}
\item 実数 $\nu>-1$ と実数 $s>0$ に対し，$\mathcal L[t^\nu](s)=\dfrac{\Gamma(\nu+1)}{s^{\nu+1}}$ を示せ．ただし $\Gamma(z)=\int_0^\infty u^{z-1}e^{-u}du$．特に $\mathcal L[t^{-1/2}]$ を具体的に書け．
\item (1) を「逆向き」に用いると $\dfrac{1}{\sqrt t}=\dfrac{1}{\sqrt\pi}\displaystyle\int_0^\infty u^{-1/2}e^{-ut}du$（$t>0$）と書ける．これと $\displaystyle\int_0^\infty\frac{u^{p-1}}{1+u^2}du=\frac{\pi}{2\sin(\pi p/2)}$（$0<p<2$）を用いて，光の回折（フレネル積分）に現れる
\[ I=\int_0^\infty\frac{\sin t}{\sqrt t}\,dt \]
の値を求めよ．（積分順序の交換は認めてよい．）
\end{enumerate}

減衰振動子（質量 $m$，$\ddot x+\gamma\dot x+\omega_0^2x=F(t)/m$，$\gamma<2\omega_0$）が静止している．時刻 $t=0$ に力積 $P_1>0$ を加え，時刻 $t=\tau>0$ に同じ向きの力積 $P_2>0$ を加える：$F(t)=P_1\delta(t)+P_2\delta(t-\tau)$．$\omega_d=\sqrt{\omega_0^2-\gamma^2/4}$ とする．
\begin{enumerate}
\item ラプラス変換を用いて，$t>\tau$ での $x(t)$ を求めよ（$t=0$ の撃力は $\mathcal L[\delta(t)]=1$ として扱う）．
\item $t>\tau$ で振動子が完全に静止する（$x\equiv0$）ための最小の $\tau$ と，そのときの $P_2/P_1$ を求めよ．
\item 減衰がない場合（$\gamma=0$）に (2) の結果はどうなるか．また減衰がある場合に $P_2=P_1$ では止められない理由を述べよ．
\end{enumerate}

周期 $2L$ ののこぎり波 $f(x)=x/L$（$-L<x<L$）を考える．
\begin{enumerate}
\item $f$ のフーリエ級数を求めよ．
\item パーセバルの等式を用いて $\displaystyle\sum_{n=1}^\infty\frac1{n^2}$ の値を求めよ．
\item 第 $N$ 部分和 $S_N(x)$ は不連続点 $x=L$ の手前で最大値をとる．$N\to\infty$ でその最大値は $1$ に近づかず，$\dfrac{2}{\pi}\mathrm{Si}(\pi)$（$\mathrm{Si}(u)=\int_0^u\frac{\sin t}{t}dt$）に近づくことを示し，数値（有効数字 3 桁）を求めよ．跳びの大きさに対するオーバーシュートの割合も答えよ．
\end{enumerate}

拡散方程式 $\dfrac{\partial u}{\partial t}=D\dfrac{\partial^2u}{\partial x^2}$ を考える．フーリエ変換 $\tilde u(k,t)=\displaystyle\int u\,e^{-ikx}dx$ を用いてよい．
\begin{enumerate}
\item 全直線上で初期条件 $u(x,0)=\delta(x)$ に対する解（基本解）$K(x,t)$ を求めよ．
\item 半直線 $x>0$ で，吸収壁の境界条件 $u(0,t)=0$ と初期条件 $u(x,0)=\delta(x-x_0)$（$x_0>0$）を満たす解を $K$ を用いて表した式を，$x,\,x_0,\,D,\,t$ で書け．
\item (2) の粒子がまだ吸収されていない確率（生存確率）$S(t)=\displaystyle\int_0^\infty u\,dx$ の，$t\gg x_0^{\,2}/D$ での主要項を求めよ．
\end{enumerate}

ポアソン和公式 $\displaystyle\sum_{n=-\infty}^{\infty}f(n)=\sum_{m=-\infty}^{\infty}\tilde f(2\pi m)$（$\tilde f(k)=\int f(x)e^{-ikx}dx$）を使う．$a>0$ とする．
\begin{enumerate}
\item $\displaystyle\sum_n\delta(x-n)=\sum_m e^{2\pi imx}$ を用いてポアソン和公式を導け．
\item $f(x)=e^{-ax^2}$ に適用して $\displaystyle\sum_{n}e^{-an^2}=\sqrt{\frac{\pi}{a}}\sum_m e^{-\pi^2m^2/a}$ を示し，$a$ が小さいときの $\displaystyle\sum_n e^{-an^2}$ を $m=0,\pm1$ の項まで残した式で表せ．
\item $\displaystyle\sum_n e^{-an^2}$ を $\sqrt{\pi/a}$ で近似したときの相対誤差を，$a=1$ について求めよ．
\end{enumerate}
